// AI CURADOR - Fase 1: Sabueso
// Limpia y normaliza los artículos crudos de RSS
const items = $input.all();
const cleaned = [];
const seen = new Set();

for (const item of items) {
  const j = item.json;
  const title = (j.title || '').trim();
  const link = (j.link || j.guid || '').trim();
  const desc = (j.contentSnippet || j.description || j.content || '').replace(/<[^>]*>/g, '').substring(0, 500);
  const pubDate = j.pubDate || j.isoDate || new Date().toISOString();
  const source = j.creator || j.author || 'Unknown';

  // Deduplicar por titulo
  const key = title.toLowerCase().replace(/[^a-z0-9]/g, '');
  if (key.length < 10 || seen.has(key)) continue;
  seen.add(key);

  // Filtrar: solo articulos sobre IA/tech/negocios
  const keywords = ['ai', 'artificial', 'intelligence', 'machine learning', 'automation', 'digital', 'tech', 'business', 'strategy', 'innovation', 'agent', 'llm', 'gpt', 'model'];
  const text = (title + ' ' + desc).toLowerCase();
  const relevant = keywords.some(k => text.includes(k));

  if (relevant) {
    cleaned.push({
      json: {
        title: title,
        url: link,
        description: desc,
        published: pubDate,
        source: source,
        relevance_score: keywords.filter(k => text.includes(k)).length
      }
    });
  }
}

// Ordenar por relevancia y tomar top 10
cleaned.sort((a, b) => b.json.relevance_score - a.json.relevance_score);
return cleaned.slice(0, 10);

// GUARDRAILS POST-CURADOR
const items = $input.all();
const valid = [];
const alerts = [];

for (const item of items) {
  const j = item.json;

  // G1: Titulo presente y no vacio
  if (!j.title || j.title.trim().length < 5) {
    alerts.push('Articulo sin titulo valido descartado');
    continue;
  }

  // G2: URL presente
  if (!j.url || !j.url.startsWith('http')) {
    alerts.push(`Articulo "${j.title}" sin URL valida`);
    continue;
  }

  // G3: Descripcion minima
  if (!j.description || j.description.length < 20) {
    j.description = j.title; // fallback
  }

  valid.push({ json: j });
}

if (valid.length === 0) {
  return [{ json: { error: 'No hay articulos validos despues de curar', alerts } }];
}

return valid;

// AI DIRECTOR CREATIVO - Fase 2: Estratega
// Filtra duplicados vs Context Graph y selecciona los mejores temas
const items = $input.all();

// Separar articulos nuevos vs memoria
const articulos = [];
const memoria = [];

for (const item of items) {
  const j = item.json;
  if (j.topic || j.status) {
    memoria.push(j);
  } else if (j.title) {
    articulos.push(j);
  }
}

// Filtrar duplicados contra Context Graph
const temasUsados = memoria.map(m => (m.topic || '').toLowerCase());
const nuevos = articulos.filter(a => {
  const titulo = a.title.toLowerCase();
  return !temasUsados.some(t => {
    if (!t) return false;
    const words = t.split(' ').filter(w => w.length > 4);
    return words.filter(w => titulo.includes(w)).length >= 2;
  });
});

if (nuevos.length === 0) {
  return [{ json: { skip: true, reason: 'Todos los articulos ya fueron cubiertos' } }];
}

// Preparar para el AI Director Creativo
return [{
  json: {
    articulos_disponibles: nuevos.slice(0, 5),
    articulos_count: nuevos.length,
    memoria_count: memoria.length,
    temas_ya_cubiertos: temasUsados.slice(-10)
  }
}];

