// G1: selected_article presente
if (!data.selected_article || !data.selected_article.title) {
  return [{ json: { error: 'No se selecciono ningun articulo', data } }];
}

// G2: hook presente y en mayusculas
if (!data.hook) {
  data.hook = data.selected_article.title.toUpperCase().split(' ').slice(0, 8).join(' ');
  alerts.push('Hook generado automaticamente del titulo');
} else {
  data.hook = data.hook.toUpperCase();
}

// G3: hook max 8 palabras
const hookWords = data.hook.split(' ');
if (hookWords.length > 10) {
  data.hook = hookWords.slice(0, 8).join(' ');
  alerts.push('Hook recortado a 8 palabras');
}

// G4: editorial_angle presente
if (!data.editorial_angle) {
  data.editorial_angle = 'Analisis de tendencia tech para profesionales';
  alerts.push('Angulo editorial por defecto aplicado');
}

// G5: target_emotion valida
const validEmotions = ['curiosidad', 'urgencia', 'aspiracion', 'revelacion'];
if (!validEmotions.includes(data.target_emotion)) {
  data.target_emotion = 'curiosidad';
}

data.guardrails_alerts = alerts;
