// GUARDRAILS POST-COPYWRITER
const raw = $input.first().json;
let data;

try {
  const content = raw.message?.content || raw.choices?.[0]?.message?.content || JSON.stringify(raw);
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  data = JSON.parse(jsonMatch[0]);
} catch (e) {
  return [{ json: { error: 'Copywriter no devolvio JSON valido', raw } }];
}

const alerts = [];

// G1: 5-6 slides obligatorio
if (!data.slides || data.slides.length < 5) {
  return [{ json: { error: 'Menos de 5 slides generados', data } }];
}
if (data.slides.length > 6) {
  data.slides = data.slides.slice(0, 6);
  alerts.push('Recortado a 6 slides');
}

// G2: Cada slide tiene layer_title_text
for (const slide of data.slides) {
  if (!slide.layer_title_text || slide.layer_title_text.trim() === '') {
    alerts.push(`Slide ${slide.number}: falta titulo`);
    slide.layer_title_text = 'AURA STUDIO';
  }
}

// G3: Titulo max 10 palabras
for (const slide of data.slides) {
  const words = slide.layer_title_text.split(' ');
  if (words.length > 10) {
    slide.layer_title_text = words.slice(0, 10).join(' ');
    alerts.push(`Slide ${slide.number}: titulo recortado a 10 palabras`);
  }
}

// G4: Body max 30 palabras
for (const slide of data.slides) {
  if (slide.layer_body_text) {
    const words = slide.layer_body_text.split(' ');
    if (words.length > 30) {
      slide.layer_body_text = words.slice(0, 30).join(' ');
      alerts.push(`Slide ${slide.number}: body recortado a 30 palabras`);
    }
  }
}

// G5: Footer default
for (const slide of data.slides) {
  if (!slide.layer_footer_text || slide.layer_footer_text.trim() === '') {
    slide.layer_footer_text = 'AURA STUDIO | 2026';
  }
}

// G6: Hashtag #AuraStudio obligatorio
if (!data.hashtags) data.hashtags = [];
if (!data.hashtags.includes('#AuraStudio')) {
  data.hashtags.unshift('#AuraStudio');
}
if (!data.hashtags.includes('#WorkFastLiveSlow')) {
  data.hashtags.push('#WorkFastLiveSlow');
}

// G7: CTA valido
const validCTAs = ['comenta', 'guarda', 'comparte'];
if (!data.cta || !validCTAs.includes(data.cta.toLowerCase())) {
  data.cta = 'comenta';
}

data.guardrails_alerts = alerts;
return [{ json: data }];

