  const jsonMatch = content.match(/\{[\s\S]*\}/);
  data = JSON.parse(jsonMatch[0]);
} catch (e) {
  return [{ json: { error: 'Director de Arte no devolvio JSON valido', raw } }];
}

const alerts = [];
const prohibited = ['robot', 'circuit', 'neon', 'cyberpunk', 'matrix', 'motherboard', 'generic office', 'futuristic', 'sci-fi', 'hologram'];

for (const bg of data.backgrounds) {
  let prompt = bg.background_image_prompt || '';

  // G6: Verificar 'no text' al final
  if (!prompt.includes('no text')) {
    prompt += ', no text, no typography, no letters, 1080x1080, 8k';
    alerts.push(`Slide ${bg.slide_number}: agregado 'no text' al prompt`);
  }

  // G7: Palabras prohibidas
  for (const word of prohibited) {
    if (prompt.toLowerCase().includes(word)) {
      prompt = prompt.replace(new RegExp(word, 'gi'), 'tropical nature');
      alerts.push(`Slide ${bg.slide_number}: '${word}' reemplazado por 'tropical nature'`);
    }
  }

  bg.background_image_prompt = prompt;
}

data.guardrails_alerts = alerts;
return [{ json: data }];

// COMPILAR: Unir textos del Copywriter con fondos del Director de Arte
// y preparar el JSON final del carrusel
const arteData = $input.first().json;

// Necesitamos los datos del copywriter del nodo anterior
// Los slides vienen del guardrails copy y los backgrounds del guardrails arte
const copyData = $('19. Guardrails Copy').first().json;

const slides = copyData.slides.map(slide => {
  const bg = arteData.backgrounds.find(b => b.slide_number === slide.number);
  return {
    number: slide.number,
    type: slide.type || 'content',
    layer_title_text: slide.layer_title_text,
    layer_body_text: slide.layer_body_text || '',
    layer_footer_text: slide.layer_footer_text || 'AURA STUDIO | 2026',
    background_image_prompt: bg ? bg.background_image_prompt : 'Cinematic editorial photography of Colombian mountain landscape, morning golden light, deep greens, no text, no typography, no letters, 1080x1080, 8k'
  };
});

const propuesta = $('17. Leer Propuesta Pendiente').first().json;

const carrusel = {
  meta: {
    topic: propuesta.topic || copyData.slides[0].layer_title_text,
    source: propuesta.source || 'Unknown',
    source_url: propuesta.source_url || '',
    generated_at: new Date().toISOString()
  },
  design_settings: {
    template_id: 'aura_carousel_v1',
    primary_color: '#1B4332',
    accent_color: '#D4A574',
    background_color: '#1A1A2E',
    font_title: 'Kaneda Gothic Bold',
    font_body: 'Inter Regular',
    logo_variant: 'cream',
    logo_position: 'bottom_right'
  },
  slides: slides,
  caption: copyData.caption || '',
  hashtags: copyData.hashtags || ['#AuraStudio', '#WorkFastLiveSlow'],
  cta: copyData.cta || 'comenta'
};

return [{ json: carrusel }];

// SEPARAR SLIDES para generar imagenes individualmente
const carrusel = $input.first().json;
const slides = carrusel.slides || [];

return slides.map(slide => ({
  json: {
    slide_number: slide.number,
    prompt: slide.background_image_prompt,
    carrusel_meta: carrusel.meta,
    design_settings: carrusel.design_settings
  }
}));

// Recopilar todas las imagenes generadas y compilar resultado final
const items = $input.all();
const carrusel = $('22. Compilar Carrusel').first().json;

// Agregar URLs de imagenes a cada slide
for (const item of items) {
  const slideNum = item.json.slide_number;
  const imageUrl = item.json.data?.[0]?.url || '';
  const slide = carrusel.slides.find(s => s.number === slideNum);
  if (slide) {
    slide.background_image_url = imageUrl;
  }
}

return [{ json: carrusel }];

// PLACEHOLDER - Rendering con Bannerbear/Creatomate
// Cuando tengas la API, descomentar y configurar
// Por ahora, pasa el carrusel tal cual con las URLs de DALL-E

