// Filtrar solo rechazados de esta semana
const items = $input.all();
const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const rechazados = items.filter(item => {
  const j = item.json;
  if (j.status !== 'rejected') return false;
  const date = new Date(j.date);
  return date >= weekAgo;
});

const publicados = items.filter(item => {
  const j = item.json;
  if (j.status !== 'published') return false;
  const date = new Date(j.date);
  return date >= weekAgo;
});

if (rechazados.length === 0) {
  return [{ json: { skip: true, publicados_count: publicados.length } }];
}

return [{
  json: {
    rechazados: rechazados.map(r => r.json),
    rechazados_count: rechazados.length,
    publicados_count: publicados.length,
    semana: `${weekAgo.toISOString().split('T')[0]} - ${now.toISOString().split('T')[0]}`
  }
}];

