// Guardrails Recap + formatear mensaje
const raw = $input.first().json;
let data;

try {
  const content = raw.message?.content || raw.choices?.[0]?.message?.content || JSON.stringify(raw);
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  data = JSON.parse(jsonMatch[0]);
} catch (e) {
  data = { rescued: [], weekly_summary: 'No se pudo generar recap' };
}

const semana = $('35. Filtrar Rechazados Semana').first().json.semana;
const pubCount = $('35. Filtrar Rechazados Semana').first().json.publicados_count;
const rechCount = $('35. Filtrar Rechazados Semana').first().json.rechazados_count;

let msg = `📊 *RECAP SEMANAL - Aura Studio*\n`;
msg += `📅 ${semana}\n\n`;
msg += `✅ Publicados: ${pubCount}\n`;
msg += `❌ Rechazados: ${rechCount}\n\n`;

if (data.rescued && data.rescued.length > 0) {
  msg += `♻️ *Rescatados con nuevo angulo:*\n`;
  for (const r of data.rescued) {
    msg += `\n• *${r.original_topic}*\n  → Nuevo angulo: ${r.new_angle}\n  → Razon: ${r.why_rescue}\n`;
  }
}

if (data.weekly_summary) {
  msg += `\n📝 *Resumen:* ${data.weekly_summary}`;
}

return [{ json: { message: msg, data } }];
